class Solution {
    public int[] stackDeck(int[] cards) {
        int n = cards.length;
        int[] sorted = cards.clone();
        Arrays.sort(sorted);
        List<Integer> deck = new ArrayList<>();
        for (int k = n - 1; k >= 0; k--) {
            if (!deck.isEmpty()) deck.add(0, deck.remove(deck.size() - 1));
            deck.add(0, sorted[k]);
        }
        int[] out = new int[n];
        for (int i = 0; i < n; i++) out[i] = deck.get(i);
        return out;
    }
}

