static int descending(const void* a, const void* b) {
    int x = *(const int*) a, y = *(const int*) b;
    return (y > x) - (y < x);
}

int* stackDeck(int* cards, int cardsSize, int* returnSize) {
    int n = cardsSize, size = 0;
    int* sorted = malloc(n * sizeof(int));
    memcpy(sorted, cards, n * sizeof(int));
    qsort(sorted, n, sizeof(int), descending);
    int* deck = malloc(n * sizeof(int));
    for (int k = 0; k < n; k++) {
        if (size > 0) {
            int bottom = deck[size - 1];
            memmove(deck + 1, deck, (size - 1) * sizeof(int));
            deck[0] = bottom;
        }
        memmove(deck + 1, deck, size * sizeof(int));
        deck[0] = sorted[k];
        size++;
    }
    free(sorted);
    *returnSize = n;
    return deck;
}

