from collections import deque

class Solution:
    def stackDeck(self, cards: List[int]) -> List[int]:
        n = len(cards)
        spots = deque(range(n))
        deck = [0] * n
        for card in sorted(cards):
            deck[spots.popleft()] = card
            if spots:
                spots.append(spots.popleft())
        return deck

