class Solution {
    public int[] stackDeck(int[] cards) {
        int n = cards.length;
        int[] spots = new int[2 * n], deck = new int[n];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) spots[tail++] = i;
        int[] sorted = cards.clone();
        Arrays.sort(sorted);
        for (int card : sorted) {
            deck[spots[head++]] = card;
            if (head < tail) spots[tail++] = spots[head++];
        }
        return deck;
    }
}

