class Solution {
public:
    vector<int> stackDeck(vector<int>& cards) {
        int n = cards.size();
        deque<int> spots;
        for (int i = 0; i < n; i++) spots.push_back(i);
        vector<int> deck(n), sorted = cards;
        sort(sorted.begin(), sorted.end());
        for (int card : sorted) {
            deck[spots.front()] = card;
            spots.pop_front();
            if (!spots.empty()) {
                spots.push_back(spots.front());
                spots.pop_front();
            }
        }
        return deck;
    }
};

