int* stackDeck(int* cards, int cardsSize, int* returnSize) {
    int n = cardsSize;
    int* spots = malloc(2 * n * sizeof(int));
    int* deck = malloc(n * sizeof(int));
    int* sorted = malloc(n * sizeof(int));
    int head = 0, tail = 0;
    for (int i = 0; i < n; i++) spots[tail++] = i;
    memcpy(sorted, cards, n * sizeof(int));
    qsort(sorted, n, sizeof(int), ascending);
    for (int k = 0; k < n; k++) {
        deck[spots[head++]] = sorted[k];
        if (head < tail) spots[tail++] = spots[head++];
    }
    free(spots);
    free(sorted);
    *returnSize = n;
